TEMPLATE = "import itertools\nimport numpy as np\nBG=__BG__\nFG=__FG__\nDOT=__DOT__\n\n\ndef _render(grid,hypothesis):\n    a=np.asarray(grid,dtype=int)\n    if a.ndim!=2 or min(a.shape)<3:raise ValueError('Grid too small')\n    ys,xs=np.nonzero(a==FG);n=int(np.sum(a==DOT))\n    if not len(ys) or not n:raise ValueError('Missing sprite or repeat dots')\n    if np.any((a!=BG)&(a!=FG)&(a!=DOT)):raise ValueError('Unexpected colour')\n    starts=[]\n    for coords,limit,mode in zip((ys,xs),a.shape,hypothesis[:2]):\n        lo,hi=int(coords.min()),int(coords.max());span=hi-lo+1\n        if span>3:raise ValueError('Sprite exceeds tile')\n        start=(hi-2,lo,lo-(3-span)//2)[mode]\n        starts.append(max(0,min(limit-3,start)))\n    y,x=starts;tile=a[y:y+3,x:x+3].copy();tile[tile==DOT]=BG\n    return np.tile(tile,(1,n) if hypothesis[2]==0 else (n,1))\n\n\ndef solve(demonstrations,grid):\n    if not demonstrations:raise ValueError('Demonstrations required')\n    alive=[]\n    for hyp in itertools.product(range(3),range(3),range(2)):\n        try:\n            if all(np.array_equal(_render(p['input'],hyp),np.asarray(p['output'])) for p in demonstrations):alive.append(hyp)\n        except ValueError:continue\n    if not alive:raise ValueError('No uniform demonstrated crop/repetition rule')\n    answers=[_render(grid,hyp) for hyp in alive]\n    if any(not np.array_equal(ans,answers[0]) for ans in answers[1:]):raise ValueError('Crop/repetition rule remains ambiguous')\n    return answers[0].tolist()\n"

def build_program(d4,palette):
    return TEMPLATE.replace("__BG__",str(int(palette[0]))).replace("__FG__",str(int(palette[8]))).replace("__DOT__",str(int(palette[4])))
